<script>
(function(){
    function escapeHtml(t){ if(!t) return ''; var d = document.createElement('div'); d.textContent = t; return d.innerHTML; }

    function updateHeight(){ 
        setTimeout(function(){ 
            var h = document.body.scrollHeight; 
            if(window.parent && window.parent !== window) {
                window.parent.postMessage({type:'resizeIframe', height:h}, '*'); 
            }
        }, 50); 
    }

    function extractRawItem(){
        var el = document.getElementById('itemRawData');
        return el ? (el.value || el.textContent || '').trim() : '';
    }

    function parseItemContent(raw) {
        var result = {
            name: '',
            type: '',
            rarity: '',
            rarityClass: 'common',
            level: '',
            attributes: [],
            special: '',
            source: '',
            appearance: ''
        };

        if(!raw || !raw.trim()) return result;

        // 解析名称
        var nameMatch = raw.match(/\*\*物品名称\*\*[：:]\s*([^\n]+)/i);
        if(nameMatch) result.name = nameMatch[1].trim();

        // 解析类型
        var typeMatch = raw.match(/\*\*物品类型\*\*[：:]\s*([^\n]+)/i);
        if(typeMatch) result.type = typeMatch[1].trim();

        // 解析稀有度
        var rarityMatch = raw.match(/\*\*稀有度层级\*\*[：:]\s*([^\n]+)/i);
        if(rarityMatch) {
            result.rarity = rarityMatch[1].trim();
            // 确定稀有度样式类
            var r = result.rarity.toLowerCase();
            if(r.indexOf('普通') !== -1) result.rarityClass = 'common';
            else if(r.indexOf('精良') !== -1) result.rarityClass = 'fine';
            else if(r.indexOf('稀有') !== -1) result.rarityClass = 'rare';
            else if(r.indexOf('史诗') !== -1) result.rarityClass = 'epic';
            else if(r.indexOf('传说') !== -1) result.rarityClass = 'legendary';
        }

        // 解析等级/需求
        var levelMatch = raw.match(/\*\*物品等级(?:\/需求)?\*\*[：:]\s*([^\n]+)/i);
        if(levelMatch) result.level = levelMatch[1].trim();

        // 解析属性/效果
        var attrSection = raw.match(/\*\*核心属性(?:\/效果)?\*\*[：:]?\n([\s\S]*?)(?=\n\s*(?:\*\s*)?\*\*(?:特殊能力(?:\/背景)?|特殊|来源(?:\/获得方式)?|来源|外观描述)|$)/i);
        if(attrSection) {
            var attrText = attrSection[1];
            var attrMatches = attrText.matchAll(/\*\*([^*]+)\*\*[：:]\s*([^\n]+(?:\n(?!\s*(?:\*\s*)?\*\*)[^\n]*)*)/gi);
            var am = attrMatches.next();
            while(!am.done) {
                result.attributes.push({
                    name: am.value[1].trim(),
                    desc: am.value[2].trim()
                });
                am = attrMatches.next();
            }
        }

        // 解析特殊能力/背景
        var specialMatch = raw.match(/\*\*特殊能力(?:\/背景)?\*\*[：:]?\n([\s\S]*?)(?=\n\s*(?:\*\s*)?\*\*(?:来源(?:\/获得方式)?|来源|外观描述)|$)/i);
        if(specialMatch) {
            // 合并多行内容
            var lines = specialMatch[1].trim().split('\n');
            var cleanLines = [];
            lines.forEach(function(line) {
                var cleaned = line.replace(/^\s*\*\s*/, '').trim();
                if(cleaned) cleanLines.push(cleaned);
            });
            result.special = cleanLines.join(' ');
        }

        // 解析来源
        var sourceMatch = raw.match(/\*\*来源(?:\/获得方式)?\*\*[：:]\s*([^\n]+(?:\n(?!\s*(?:\*\s*)?\*\*)[^\n]*)*)/i);
        if(sourceMatch) result.source = sourceMatch[1].trim();

        // 解析外观
        var appearMatch = raw.match(/\*\*外观描述[^\n]*\*\*[：:]\s*([^\n]+(?:\n(?!\s*(?:\*\s*)?\*\*)[^\n]*)*)/i);
        if(appearMatch) result.appearance = appearMatch[1].trim();

        return result;
    }

    function getItemIcon(type) {
        if(!type) return '📦';
        var t = type.toLowerCase();
        if(t.indexOf('武器') !== -1) return '⚔️';
        if(t.indexOf('防具') !== -1) return '🛡️';
        if(t.indexOf('饰品') !== -1) return '💍';
        if(t.indexOf('消耗品') !== -1) return '🧪';
        if(t.indexOf('任务') !== -1) return '📋';
        if(t.indexOf('材料') !== -1) return '💎';
        return '📦';
    }

    function renderRarityName(rarity, rarityClass) {
        var colors = {
            'common': '#6b6b6b',
            'fine': '#2a8b4a',
            'rare': '#2a5a8b',
            'epic': '#6b2a8b',
            'legendary': '#8b6a1a'
        };
        return '<span style="color:' + colors[rarityClass] + '">' + escapeHtml(rarity) + '</span>';
    }

    function renderItem(data) {
        if(!data.name) return '<div class="empty-state">等待物品数据...</div>';

        var html = '<div class="item-header">';
        html += '<div class="item-icon">' + getItemIcon(data.type) + '</div>';
        html += '<div class="item-name" style="color: var(--rarity-' + data.rarityClass + ')">' + escapeHtml(data.name) + '</div>';
        html += '<span class="rarity-badge ' + data.rarityClass + '">' + escapeHtml(data.rarity || '普通') + '</span>';
        if(data.type) html += '<div class="type-tag">' + escapeHtml(data.type) + '</div>';
        html += '</div>';

        // 信息网格
        if(data.level) {
            html += '<div class="info-grid">';
            html += '<div class="info-card"><div class="info-label">📊 等级需求</div>';
            html += '<div class="info-value">' + escapeHtml(data.level) + '</div></div>';
            html += '</div>';
        }

        // 核心属性
        if(data.attributes.length > 0) {
            html += '<div class="section"><div class="section-title">核心属性</div>';
            data.attributes.forEach(function(attr) {
                html += '<div class="attribute-item"><div class="attribute-name">' + escapeHtml(attr.name) + '</div>';
                html += '<div class="attribute-desc">' + escapeHtml(attr.desc) + '</div></div>';
            });
            html += '</div>';
        }

        // 特殊能力/背景
        if(data.special) {
            html += '<div class="section special-section"><div class="section-title">特殊能力与背景</div>';
            html += '<div class="special-content">' + escapeHtml(data.special) + '</div></div>';
        }

        // 来源
        if(data.source) {
            html += '<div class="source-section"><div class="source-label">📍 来源</div>';
            html += '<div class="source-value">' + escapeHtml(data.source) + '</div></div>';
        }

        // 外观描述
        if(data.appearance) {
            html += '<div class="appearance-section"><div class="appearance-label">👁 外观描述</div>';
            html += '<div class="appearance-content">' + escapeHtml(data.appearance) + '</div></div>';
        }

        return html;
    }

    function initItem() {
        var container = document.getElementById('itemContent');
        var raw = extractRawItem();

        if(!raw || !raw.trim()) {
            container.innerHTML = '<div class="empty-state">等待物品数据...</div>';
            return;
        }

        var parsed = parseItemContent(raw);
        container.innerHTML = renderItem(parsed);
        updateHeight();
    }

    if(document.readyState === 'complete' || document.readyState === 'interactive') setTimeout(initItem, 0);
    document.addEventListener('DOMContentLoaded', initItem);
    setTimeout(initItem, 100);
    setTimeout(initItem, 300);
})();
</script>
</body>
